# Walk outward from the apex through the airborne arc to the first
# ground-contact frame on each side: takeoff (before) and landing (after).
takeoff = apex
for f in range(apex - 1, -1, -1):
    if not present[f]:
        continue
    if sb[f] >= edge_thr:
        takeoff = f
        break
    takeoff = f  # keep last present airborne frame as fallback
for f in range(apex - 1, -1, -1):
    if present[f] and sb[f] >= edge_thr:
        takeoff = f
        break

landing = apex
for f in range(apex + 1, n):
    if present[f] and sb[f] >= edge_thr:
        landing = f
        break

return int(takeoff), int(landing)

edits.new:
# Walk outward from the apex to the first ground-contact frame on each
# side: takeoff (before) and landing (after). Fall back to the last known
# present frame on that side if the ground is never re-reached.
takeoff = apex
for f in range(apex - 1, -1, -1):
    if present[f]:
        takeoff = f
        if sb[f] >= edge_thr:
            break

landing = apex
for f in range(apex + 1, n):
    if present[f]:
        landing = f
        if sb[f] >= edge_thr:
            break

return int(takeoff), int(landing)
